import math

def is_perfect_cube(n):
    if n < 0:
        return None
    root = round(n**(1/3))
    if root**3 == n:
        return root
    return None

def is_prime(n):
    if n < 2:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

test_primes = [2, 3, 5, 7]
results = []

for q in test_primes:
    value = q**2 - q + 1
    p = is_perfect_cube(value)

    result = {
        'q': q,
        'value': value,
        'p': None,
        'is_cube': False,
        'p_is_prime': False,
        'p_not_equal_to_q': False
    }

    if p is not None:
        result['p'] = p
        result['is_cube'] = True
        if is_prime(p):
            result['p_is_prime'] = True
            if p != q:
                result['p_not_equal_to_q'] = True

    results.append(result)

print("--- Results ---")
for res in results:
    print(f"q={res['q']}: q^2 - q + 1 = {res['value']}. Is perfect cube? {res['is_cube']}. If yes, p={res['p']}. Is p prime and p != q? {res['p_is_prime'] and res['p_not_equal_to_q']}")
